class Policy:
    # Changed from pure round-robin to round-robin with a "sticky" bias:
    # once a task achieves a perfect score, keep selecting it (it's solved),
    # otherwise fall back to round-robin to explore other tasks.
    def __init__(self):
        self.scores = {}  # task_id -> list of recent scores
        self.perfect_tasks = set()  # tasks that have scored 1.0

    def pick(self, keys, round_index):
        # Prefer any task that has been perfect (solved) – keep exploiting it.
        for task in keys:
            if task in self.perfect_tasks:
                return task
        # Otherwise round-robin over the keys.
        return keys[round_index % len(keys)]

    def record(self, task_id, score):
        # Track scores; if a task ever gets 1.0, mark it as solved.
        if score >= 1.0:
            self.perfect_tasks.add(task_id)
        # Keep a small history (optional, not used for decision here)
        self.scores.setdefault(task_id, []).append(score)
        # Keep only last 10 scores to avoid unbounded memory
        if len(self.scores[task_id]) > 10:
            self.scores[task_id] = self.scores[task_id][-10:]
