class Policy:
    # Changed from round-robin to UCB1-style exploration to focus on promising tasks
    # while still exploring, which helps when tasks have varying difficulty.
    def __init__(self):
        self.counts = {}
        self.rewards = {}
        self.total = 0

    def pick(self, keys, round_index):
        import math
        # First visit each task once to get initial data
        for k in keys:
            if k not in self.counts:
                return k
        # UCB1: pick task with highest upper confidence bound
        best_key = None
        best_ucb = -float('inf')
        for k in keys:
            n = self.counts[k]
            avg = self.rewards[k] / n if n > 0 else 0.0
            # exploration bonus: sqrt(2*ln(total)/n)
            bonus = math.sqrt(2 * math.log(self.total + 1) / n) if n > 0 else float('inf')
            ucb = avg + bonus
            if ucb > best_ucb:
                best_ucb = ucb
                best_key = k
        return best_key

    def record(self, task_id, score):
        if task_id not in self.counts:
            self.counts[task_id] = 0
            self.rewards[task_id] = 0.0
        self.counts[task_id] += 1
        self.rewards[task_id] += score
        self.total += 1
