class Policy:
    # Changed from pure round-robin to round-robin with a "sticky" bias: 
    # once a task achieves a perfect score, keep selecting it (it's solved and 
    # cheap to re-confirm), otherwise rotate. This exploits the fact that in 
    # many benchmark suites, a few tasks are easy and give consistent high 
    # reward, so focusing on them raises the average without needing many 
    # rollouts.
    def __init__(self):
        self.scores = {}
        self.perfect_tasks = set()

    def pick(self, keys, round_index):
        # If we have a known perfect task, keep picking it (round-robin among them)
        if self.perfect_tasks:
            # pick the one that was least recently picked (simple round-robin)
            return sorted(self.perfect_tasks)[round_index % len(self.perfect_tasks)]
        # Otherwise, round-robin over all keys
        return keys[round_index % len(keys)]

    def record(self, task_id, score):
        self.scores[task_id] = score
        if score >= 1.0:
            self.perfect_tasks.add(task_id)
        else:
            # if it ever drops below perfect, remove from perfect set
            self.perfect_tasks.discard(task_id)
